import{_ as e,o,c as a,a2 as i}from"./chunks/framework.CdvW4CUT.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"LlamaCraft","text":"Proximity Voice & Cross-Play","tagline":"Experience immersive 3D directional audio across Bedrock and Java on Minecraft 1.21+ with zero client mods.","image":{"src":"/llama.jpg","alt":"LlamaCraft Voxel Mascot"},"actions":[{"theme":"brand","text":"How to Join","link":"/guide/how-to-join"},{"theme":"alt","text":"Voice Chat Guide","link":"/guide/voice-chat"},{"theme":"alt","text":"Discord Server","link":"https://discord.gg"}]},"features":[{"title":"3D Directional Voice Chat","details":"Hear players based on their in-game location. Voices naturally fade with distance, carry through caves, and isolate behind walls."},{"title":"True Cross-Play Parity","details":"Seamlessly connects Java Edition, Bedrock Mobile, Windows PC, Consoles (Xbox, PlayStation, Switch), and Education Edition."},{"title":"Zero Bedrock Mods","details":"Bedrock players connect without jailbreaking or modifying their game. Console players use the free phone companion app."},{"title":"Grief Prevention & Claims","details":"Protect your builds, chests, and terrain with custom claim boundaries while keeping siege mechanics balanced and active."},{"title":"Player Economy & Trade","details":"Dynamic player shops, interactive menu interfaces, and trade systems built for multiplayer collaboration."},{"title":"High Performance Paper Core","details":"Hosted on dedicated hardware with optimized tick timing, anti-cheat protection, and low-latency packet routing."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function n(l,t,s,d,c,h){return o(),a("div",null,[...t[0]||(t[0]=[i('<h2 id="server-connection-information" tabindex="-1">Server Connection Information <a class="header-anchor" href="#server-connection-information" aria-label="Permalink to &quot;Server Connection Information&quot;">​</a></h2><p>Connect directly from any supported Minecraft version:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Platform</th><th style="text-align:left;">Server Address (IP)</th><th style="text-align:left;">Port</th><th style="text-align:left;">Supported Versions</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Java Edition</strong></td><td style="text-align:left;"><code>164.152.106.210</code></td><td style="text-align:left;"><code>25565</code></td><td style="text-align:left;"><code>1.20.x - 1.21.x</code></td></tr><tr><td style="text-align:left;"><strong>Bedrock (Mobile &amp; PC)</strong></td><td style="text-align:left;"><code>164.152.106.210</code></td><td style="text-align:left;"><code>19132</code></td><td style="text-align:left;"><code>1.21.x</code> (Latest)</td></tr><tr><td style="text-align:left;"><strong>Xbox / PlayStation / Switch</strong></td><td style="text-align:left;">Via Bedrock DNS / App</td><td style="text-align:left;"><code>19132</code></td><td style="text-align:left;"><code>1.21.x</code> (Latest)</td></tr><tr><td style="text-align:left;"><strong>Education Edition</strong></td><td style="text-align:left;"><code>164.152.106.210</code></td><td style="text-align:left;"><code>19132</code></td><td style="text-align:left;">Supported via Protocol</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Quick Join</p><p>No whitelist is enabled. Join the server, claim your starter kit, and explore the spawn hub.</p></div><hr><h2 id="why-in-game-proximity-voice" tabindex="-1">Why In-Game Proximity Voice? <a class="header-anchor" href="#why-in-game-proximity-voice" aria-label="Permalink to &quot;Why In-Game Proximity Voice?&quot;">​</a></h2><p>Standard Discord or party chat puts everyone into one flat room where players talk over each other regardless of where they are in the world.</p><p>LlamaCraft proximity voice chat calculates real-time 3D coordinates so voices originate from where players stand:</p><ul><li><strong>Distance Roll-Off</strong>: Voices get quieter as players walk away and fade out completely past 24 blocks.</li><li><strong>Directional Sound</strong>: Turn your character&#39;s head to pinpoint exactly where another player is calling from.</li><li><strong>Whispering and Shouting</strong>: Sneak to whisper quietly to teammates, or sprint to shout across a fortress.</li><li><strong>Console Friendly</strong>: Xbox, PS, and Switch players run the companion link on their phone while playing on TV.</li></ul>',9)])])}const m=e(r,[["render",n]]);export{y as __pageData,m as default};
